// Cart management module
import { formatMoney, escapeHtml, escapeAttr, fetchProducts } from "./utils.js";
import {
  activateDialog,
  deactivateDialog,
  setPageHidden,
  getFocusableElements,
  openModalPair,
  closeModalPair,
} from "./modal.js";

const CART_KEY = "photo-portfolio-cart";

export function getCart() {
  try {
    const raw = localStorage.getItem(CART_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    console.warn("Failed to load cart from localStorage:", e);
    return [];
  }
}

export function setCart(items) {
  try {
    localStorage.setItem(CART_KEY, JSON.stringify(items));
    updateCartBadge();
  } catch (e) {
    console.error("Failed to save cart to localStorage:", e);
  }
}

export function addToCart(product, qty) {
  qty = qty == null ? 1 : Math.max(1, parseInt(qty, 10) || 1);
  const normalized = {
    id: String(product.id),
    title: product.title,
    priceCents: Number(product.priceCents) || 0,
    currency: product.currency || "USD",
    image: product.image || "",
  };
  const line = {
    id: normalized.id,
    title: normalized.title,
    priceCents: normalized.priceCents,
    currency: normalized.currency,
    image: normalized.image,
    qty: qty,
  };
  const cart = getCart();
  const found = cart.find(function (i) {
    return i.id === line.id;
  });
  if (found) {
    found.qty += qty;
  } else {
    cart.push(line);
  }
  setCart(cart);
  console.log("[addToCart]", line, "cart:", cart);
  return cart;
}

export function getCartCount() {
  return getCart().reduce(function (sum, i) {
    return sum + (i.qty || 0);
  }, 0);
}

export function updateCartBadge() {
  const badge = document.querySelector(".cart-badge");
  if (!badge) return;
  const n = getCartCount();
  badge.textContent = n > 99 ? "99+" : String(n);
  badge.classList.toggle("is-visible", n > 0);
}

function renderCartModalBody() {
  const body = document.getElementById("cart-modal-body");
  if (!body) return;
  const cart = getCart();
  if (!cart.length) {
    body.innerHTML = '<p class="cart-empty">Your cart is empty.</p>';
    return;
  }

  const total = cart.reduce(function (s, i) {
    return s + i.priceCents * (i.qty || 1);
  }, 0);
  const currency = cart[0].currency || "USD";
  const lines = cart
    .map(function (i, idx) {
      return (
        `<li data-item-idx='${idx}' class='cart-modal-item'>
          <span class="cart-modal-item-details">${escapeHtml(i.title)}</span>
          <div class="cart-qty">
            <button type="button" class="btn btn--ghost qty-btn" data-action="decrease" data-item-idx="${idx}" data-qty="-1">−</button>
            <span class="qty-val">${(i.qty || 1)}</span>
