          });
      } else {
        currentCart[idx].qty = newQty;
        setCart(currentCart);
        renderCartPage();
      }
    }
  }

  if (target.classList.contains("trash-item-btn")) {
    const idx = parseInt(target.dataset.itemIdx, 10);
