}

function injectCartModal() {
  if (document.getElementById("modal-cart-backdrop")) return;
  const wrap = document.createElement("div");
  wrap.innerHTML = `
    <div class="modal-backdrop" id="modal-cart-backdrop" aria-hidden="true"></div>
