      closeModalPair("modal-coming-soon-backdrop", "modal-coming-soon");
    });
  }
}

export {
  handleCartPageClick,
  handleCartModalClick,
};

export {
  initCartButton,
  initComingSoonTriggers,
  renderCartModalBody,
  injectCartModal,
};

